// Render the synthetic HTML generated by TestCourseInterestEmailTemplate.
// Serves local files only; does not connect to SMTP or any external service.
const fs=require('fs'),path=require('path'),http=require('http'),os=require('os'),{spawn}=require('child_process')
const output=path.resolve(__dirname,'../.codex-run/course-interest-email'),html=fs.readFileSync(path.join(output,'course-interest-email.html'),'utf8'),sleep=ms=>new Promise(r=>setTimeout(r,ms))
const server=http.createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(html)})
;(async()=>{
 await new Promise(r=>server.listen(0,'127.0.0.1',r))
 const profile=fs.mkdtempSync(path.join(os.tmpdir(),'ft-interest-email-'))
 const browser=spawn(process.env.EDGE_PATH||'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',['--headless=new','--disable-gpu','--no-first-run','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{windowsHide:true,stdio:'ignore'})
 let ws
 try{
  let port;for(let n=0;n<100;n++){try{port=fs.readFileSync(path.join(profile,'DevToolsActivePort'),'utf8').split('\n')[0];break}catch{await sleep(100)}}
  if(!port)throw Error('Headless Edge unavailable')
  const tabs=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener('open',r,{once:true}))
  let seq=0;const pending=new Map()
  ws.addEventListener('message',event=>{const m=JSON.parse(event.data);if(m.id){pending.get(m.id)?.(m);pending.delete(m.id)}})
  const cmd=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,m=>m.error?reject(Error(JSON.stringify(m.error))):resolve(m.result));ws.send(JSON.stringify({id,method,params}))})
  const evaluate=async expression=>{const r=await cmd('Runtime.evaluate',{expression,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.text);return r.result.value}
  await cmd('Page.enable');await cmd('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/`})
  for(let n=0;n<100;n++){if(await evaluate(`document.body?.textContent.includes('Анна Петрова')`))break;await sleep(50)}
  for(const width of [1440,900,360]){
   await cmd('Emulation.setDeviceMetricsOverride',{width,height:1200,deviceScaleFactor:1,mobile:false});await sleep(100)
   const check=await evaluate(`({overflow:document.documentElement.scrollWidth>innerWidth,button:[...document.querySelectorAll('a')].find(a=>a.textContent.includes('Перейти в Академию'))?.href,phone:document.body.textContent.includes('+79991234567'),logo:document.querySelector('img').naturalWidth>0})`)
   if(check.overflow||!check.phone||!check.logo||check.button!=='https://fintalent.ru/profile/courses/42/academy/analytics?tab=students&period=all')throw Error('Invalid email preview: '+JSON.stringify(check))
   const shot=await cmd('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});fs.writeFileSync(path.join(output,'email-'+width+'.png'),Buffer.from(shot.data,'base64'))
   console.log('PASS email layout, contacts, logo and Academy link at '+width+'px')
  }
  console.log('Preview: '+output)
 }finally{ws?.close();browser.kill();server.close()}
})().catch(error=>{console.error(error);process.exitCode=1;server.close()})
